// The modern templates (templates/modern-*) are generated by
// scripts/modern-templates.mjs; the committed files must match its output.
// Run with `npm test`.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { readFileSync, readdirSync } from "node:fs";
import { test } from "node:test";

test("the generated modern templates are up to date", () => {
  const r = spawnSync(process.execPath, ["scripts/modern-templates.mjs", "--check"], { encoding: "utf8" });
  assert.equal(r.status, 0, r.stderr);
});

test("the modern templates load nothing from outside", () => {
  const ids = readdirSync("templates").filter((d) => d.startsWith("modern-"));
  assert.deepEqual(ids.sort(), ["modern-dark", "modern-light", "modern-orange"]);
  for (const id of ids) {
    const css = readFileSync(`templates/${id}/theme.css`, "utf8");
    assert.doesNotMatch(css, /@import|url\(|expression\(|javascript:/i, id);
  }
});
